// Pool is the typed pgx connection pool. Lives alongside sqlc-generated
// db.go / *.sql.go in this package so callers can do:
//
//	pool, _ := db.Open(ctx, db.Config{DatabaseURL: ...})
//	queries := db.New(pool)        // sqlc Queries
//	leads, _ := queries.GetLeadByPhone(ctx, db.GetLeadByPhoneParams{...})
//
// This file is hand-maintained; the others (db.go, *.sql.go, models.go)
// are generated by sqlc.
package db

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// Pool wraps pgxpool.Pool so callers depend on this package, not on pgx
// directly. The underlying pool is also a DBTX, so we hand it to
// sqlc.New() to create Queries.
type Pool struct {
	*pgxpool.Pool
}

// Config configures the pool.
type Config struct {
	DatabaseURL       string
	MaxConns          int32
	MinConns          int32
	MaxConnLifetime   time.Duration
	MaxConnIdleTime   time.Duration
	HealthCheckPeriod time.Duration
	ConnectTimeout    time.Duration
}

// Open creates a new connection pool and verifies the connection with a
// ping. Fails fast on misconfiguration.
func Open(ctx context.Context, cfg Config) (*Pool, error) {
	if cfg.DatabaseURL == "" {
		return nil, errors.New("db: DatabaseURL is required")
	}

	pcfg, err := pgxpool.ParseConfig(cfg.DatabaseURL)
	if err != nil {
		return nil, fmt.Errorf("db: parse config: %w", err)
	}

	if cfg.MaxConns > 0 {
		pcfg.MaxConns = cfg.MaxConns
	} else {
		pcfg.MaxConns = 20
	}
	if cfg.MinConns > 0 {
		pcfg.MinConns = cfg.MinConns
	} else {
		pcfg.MinConns = 2
	}
	if cfg.MaxConnLifetime > 0 {
		pcfg.MaxConnLifetime = cfg.MaxConnLifetime
	} else {
		pcfg.MaxConnLifetime = time.Hour
	}
	if cfg.MaxConnIdleTime > 0 {
		pcfg.MaxConnIdleTime = cfg.MaxConnIdleTime
	} else {
		pcfg.MaxConnIdleTime = 30 * time.Minute
	}
	if cfg.HealthCheckPeriod > 0 {
		pcfg.HealthCheckPeriod = cfg.HealthCheckPeriod
	} else {
		pcfg.HealthCheckPeriod = time.Minute
	}
	if cfg.ConnectTimeout > 0 {
		pcfg.ConnConfig.ConnectTimeout = cfg.ConnectTimeout
	} else {
		pcfg.ConnConfig.ConnectTimeout = 5 * time.Second
	}

	pool, err := pgxpool.NewWithConfig(ctx, pcfg)
	if err != nil {
		return nil, fmt.Errorf("db: connect: %w", err)
	}

	pingCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("db: ping: %w", err)
	}

	return &Pool{Pool: pool}, nil
}

// Ping checks the connection. Used by /readyz.
func (p *Pool) Ping(ctx context.Context) error {
	if p == nil || p.Pool == nil {
		return errors.New("db: pool is nil")
	}
	return p.Pool.Ping(ctx)
}

// Stats returns pool statistics (in-use, idle, max).
func (p *Pool) Stats() *pgxpool.Stat {
	if p == nil || p.Pool == nil {
		return nil
	}
	return p.Pool.Stat()
}
